//! Exclusive selected CHECK uses the actual existing Handler preparation/producer.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildRequest,BuildOutcome,Command},runner_host::{BuildHost,FullRegistryCheckOptions}};
use std::path::{Path,PathBuf};
fn put(root:&Path,relative:&str,text:impl AsRef<[u8]>){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}
fn fixture(label:&str,full:bool)->PathBuf{let root=std::fs::canonicalize(scratch::dir(label)).unwrap();put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));
 put(&root,"code/__defines/context.dm","#define CAPABILITIES(...)\n#define PROC_REF(P) #P\n/datum/act\n/datum/act/eval\n/obj/probe\n");
 put(&root,"code/structural.dm","/proc/leak(datum/act/A)\n    return list(A)\n/proc/allowed(datum/act/A)\n    return list(A) // ALLOW(handlers): preserve actual raw annotation consumption in native report\n");
 let mut manifest="#include \"code/__defines/context.dm\"\n#include \"code/structural.dm\"\n".to_owned();
 if full{put(&root,"code/handler.dm","/obj/probe/proc/handler(datum/act/eval/A)\n    return 2\nCAPABILITIES(/obj/probe,when(PROC_REF(handler)))\n");put(&root,"code/engine/present/protocols.dm","/datum/look\n/atom/proc/draw(datum/look/look)\n    return\n");put(&root,"code/output.dm","/obj/bad/draw(extra,datum/look/look)\n    return\n");manifest.push_str("#include \"code/handler.dm\"\n#include \"code/engine/present/protocols.dm\"\n#include \"code/output.dm\"\n");}
 put(&root,"deepquarry.dme",manifest);root}
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual public preparation")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.timeout_seconds=Some(60);request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(scratch::dir("selected-handler-check-cache"));request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.to_owned(),recursive_roots:["code","doc/rewrite","interface","maps","modular_chomp","tgui"].map(|part|root.join(part)).to_vec(),configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:Vec::new(),..Default::default()});request}

fn no_products(root:&Path){for item in std::fs::read_dir(root).unwrap(){let item=item.unwrap();let path=item.path();if item.file_type().unwrap().is_dir(){no_products(&path)}else{assert!(!matches!(path.extension().and_then(|v|v.to_str()),Some("dmb"|"rsc")),"{}",path.display());}}}
#[test]fn actual_selected_handler_partial_check_skips_unrequested_physical_root_and_baselines(){
 let root=fixture("selected-handler-partial",false);std::fs::remove_file(root.join("deepquarry.dme")).unwrap();std::fs::create_dir(root.join("deepquarry.dme")).unwrap();
 let mut host=BuildHost::default();for ci in [false,true]{let(mut diagnostics,mut text)=(Vec::new(),Vec::new());
  let clean=host.write_selected_registry_check(request(&root),FullRegistryCheckOptions{ci,..Default::default()},&["sem/handlers".into()],&mut diagnostics,&mut text).unwrap();
  let text=String::from_utf8(text).unwrap();assert!(!clean,"real context escape remains Hard failure");assert!(text.contains("code/structural.dm"));assert!(!text.contains("allow annotations:")&&!text.contains("base_vars"));assert_eq!(text.contains("::group::sem/handlers"),ci);assert!(root.join("deepquarry.dme").is_dir());
 }
 assert!(host.symbolic_retention_stats().is_none_or(|stats|stats.records==0&&stats.successful_admissions==0));no_products(&root);
}
#[test]fn actual_selected_handler_check_demands_only_real_full_partition_and_keeps_all_three_sections(){
 let root=fixture("selected-handler-current-full",true);let mut host=BuildHost::default();let(mut diagnostics,mut report)=(Vec::new(),Vec::new());
 assert!(!host.write_selected_registry_check(request(&root),FullRegistryCheckOptions::default(),&["sem/handlers".into()],&mut diagnostics,&mut report).unwrap());
 let report=String::from_utf8(report).unwrap();for path in ["code/structural.dm","code/handler.dm","code/output.dm"]{assert!(report.contains(path),"{path}: {report}")}
 assert!(!report.contains("allow annotations:")&&!report.contains("base_vars"));no_products(&root);
}
#[test]fn actual_selected_handler_report_preserves_first_output_io_and_same_host_recovers(){
 struct Fail;impl std::io::Write for Fail{fn write(&mut self,_:&[u8])->std::io::Result<usize>{Err(std::io::Error::from_raw_os_error(1450))}fn flush(&mut self)->std::io::Result<()>{panic!("no flush after actual IO")}}
 let root=fixture("selected-handler-current-io",true);let mut host=BuildHost::default();let mut diagnostics=Vec::new();
 let actual=host.write_selected_registry_check(request(&root),FullRegistryCheckOptions::default(),&["sem/handlers".into()],&mut diagnostics,&mut Fail).unwrap_err();
 assert_eq!(actual.downcast_ref::<std::io::Error>().unwrap().raw_os_error(),Some(1450));let mut report=Vec::new();assert!(!host.write_selected_registry_check(request(&root),FullRegistryCheckOptions::default(),&["sem/handlers".into()],&mut diagnostics,&mut report).unwrap());assert!(!report.is_empty());no_products(&root);
}

fn mixed_fixture(label:&str,full:bool)->PathBuf{
 let root=fixture(label,full);let setter=include_str!("../../../../../code/defines/engine/capabilities.dm").lines().find(|line|line.starts_with("#define SETTER(")).unwrap();put(&root,"code/tracked.dm",format!("{setter}\n/obj/probe\n    var/plain\nSETTER(/obj/probe, plain)\n/obj/probe/proc/write_plain()\n    plain = 1\n    return 0\n"));let path=root.join("deepquarry.dme");let mut manifest=std::fs::read_to_string(&path).unwrap();manifest.push_str("#include \"code/tracked.dm\"\n");std::fs::write(path,manifest).unwrap();root
}
#[test]fn actual_selected_tracked_and_handler_join_uses_real_model_and_both_issued_sections(){
 let root=mixed_fixture("selected-model-handler-full",true);std::fs::create_dir(root.join("SpacemanDMM.toml")).unwrap();let mut host=BuildHost::default();let(mut diagnostics,mut report)=(Vec::new(),Vec::new());let clean=host.write_selected_registry_check(request(&root),FullRegistryCheckOptions{raw:true,..Default::default()},&["tracked".into(),"sem/handlers".into()],&mut diagnostics,&mut report).unwrap();let text=String::from_utf8(report).unwrap();assert!(!clean);assert!(text.contains("plain written outside /obj/probe/proc/set_plain()"),"actual typed tracked body must participate: {text}");for path in["code/structural.dm","code/handler.dm","code/output.dm"]{assert!(text.contains(path),"{path}: {text}")}assert!(!text.contains("allow annotations:")&&!text.contains("base_vars"));assert!(diagnostics.is_empty(),"unrequested Checker and its nonfile config must not be opened");no_products(&root);
}
#[test]fn actual_selected_tracked_model_does_not_invent_unrequested_handler_full_partition(){
 let root=mixed_fixture("selected-model-handler-structural",false);let mut host=BuildHost::default();let(mut diagnostics,mut report)=(Vec::new(),Vec::new());assert!(!host.write_selected_registry_check(request(&root),FullRegistryCheckOptions{raw:true,..Default::default()},&["tracked".into(),"sem/handlers".into()],&mut diagnostics,&mut report).unwrap());let text=String::from_utf8(report).unwrap();assert!(text.contains("code/structural.dm")&&text.contains("plain written outside /obj/probe/proc/set_plain()"),"{text}");assert!(!text.contains("code/handler.dm")&&!text.contains("code/output.dm")&&!text.contains("allow annotations:"));no_products(&root);
}
#[test]fn actual_selected_model_handler_join_preserves_first_output_io_and_same_host_recovers(){
 struct Fail;impl std::io::Write for Fail{fn write(&mut self,_:&[u8])->std::io::Result<usize>{Err(std::io::Error::from_raw_os_error(1450))}fn flush(&mut self)->std::io::Result<()>{panic!("no flush after actual first IO")}}
 let root=mixed_fixture("selected-model-handler-io",true);let mut host=BuildHost::default();let mut diagnostics=Vec::new();let selectors=["tracked".into(),"sem/handlers".into()];let options=FullRegistryCheckOptions{raw:true,..Default::default()};let actual=host.write_selected_registry_check(request(&root),options,&selectors,&mut diagnostics,&mut Fail).unwrap_err();assert_eq!(actual.downcast_ref::<std::io::Error>().unwrap().raw_os_error(),Some(1450));let mut report=Vec::new();assert!(!host.write_selected_registry_check(request(&root),options,&selectors,&mut diagnostics,&mut report).unwrap());assert!(!report.is_empty());no_products(&root);
}

#[test]fn actual_selected_model_handler_join_real_quota_denial_refuses_then_releases_and_recovers(){
 let root=mixed_fixture("selected-model-handler-quota",true);let mut host=BuildHost::default();let limit=host.source_arena_work().transformed_source_address_limit().unwrap();let pressure=host.source_arena_work().reserve(limit-512*1024).unwrap();let selectors=["tracked".into(),"sem/handlers".into()];let options=FullRegistryCheckOptions{raw:true,..Default::default()};let(mut diagnostics,mut report)=(Vec::new(),Vec::new());let error=host.write_selected_registry_check(request(&root),options,&selectors,&mut diagnostics,&mut report).unwrap_err();assert_eq!(error.downcast_ref::<std::io::Error>().unwrap().kind(),std::io::ErrorKind::OutOfMemory);assert!(diagnostics.is_empty()&&report.is_empty());drop(pressure);assert!(!host.write_selected_registry_check(request(&root),options,&selectors,&mut diagnostics,&mut report).unwrap());assert!(!report.is_empty());no_products(&root);
}
#[test]fn actual_selected_model_handler_failed_full_source_cannot_complete_from_staged_partial_rows(){
 let root=mixed_fixture("selected-model-handler-full-failure",true);put(&root,"maps/fail.dm","#error FAILED_SELECTED_FULL_SOURCE\n");let path=root.join("deepquarry.dme");let mut manifest=std::fs::read_to_string(&path).unwrap();manifest.push_str("#include \"maps/fail.dm\"\n");std::fs::write(path,manifest).unwrap();let mut host=BuildHost::default();let(mut diagnostics,mut report)=(Vec::new(),Vec::new());let error=host.write_selected_registry_check(request(&root),FullRegistryCheckOptions{raw:true,..Default::default()},&["tracked".into(),"sem/handlers".into()],&mut diagnostics,&mut report).unwrap_err();assert!(!error.to_string().is_empty());assert!(diagnostics.is_empty()&&report.is_empty(),"failed full source must not publish a completed or partial selected report");no_products(&root);
}
#[test]fn actual_selected_model_handler_same_stamp_configuration_mutation_refuses_and_recovers(){
 use std::io::Write;struct Restore{path:PathBuf,bytes:Vec<u8>,modified:std::time::SystemTime}impl Drop for Restore{fn drop(&mut self){std::fs::write(&self.path,&self.bytes).unwrap();std::fs::OpenOptions::new().write(true).open(&self.path).unwrap().set_times(std::fs::FileTimes::new().set_modified(self.modified)).unwrap();}}
 struct Change<'a>{restore:&'a Restore,changed:bool,bytes:Vec<u8>}impl Write for Change<'_>{fn write(&mut self,bytes:&[u8])->std::io::Result<usize>{self.bytes.extend_from_slice(bytes);if !self.changed{let mut altered=self.restore.bytes.clone();let offset=altered.windows(b"HANDLER_SAME_STAMP_A".len()).position(|part|part==b"HANDLER_SAME_STAMP_A").unwrap();altered[offset+b"HANDLER_SAME_STAMP_A".len()-1]=b'B';assert_eq!(altered.len(),self.restore.bytes.len());std::fs::write(&self.restore.path,altered)?;std::fs::OpenOptions::new().write(true).open(&self.restore.path)?.set_times(std::fs::FileTimes::new().set_modified(self.restore.modified))?;self.changed=true;}Ok(bytes.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
 let root=mixed_fixture("selected-model-handler-config-stale",true);let path=root.join("tools/ci/lint_scopes.toml");let mut bytes=std::fs::read(&path).unwrap();bytes.extend_from_slice(b"\n# HANDLER_SAME_STAMP_A\n");std::fs::write(&path,&bytes).unwrap();let restore=Restore{modified:std::fs::metadata(&path).unwrap().modified().unwrap(),path,bytes};let mut host=BuildHost::default();let(mut diagnostics,mut sink)=(Vec::new(),Change{restore:&restore,changed:false,bytes:Vec::new()});let selectors=["tracked".into(),"sem/handlers".into()];let options=FullRegistryCheckOptions{raw:true,..Default::default()};let error=host.write_selected_registry_check(request(&root),options,&selectors,&mut diagnostics,&mut sink).unwrap_err();assert!(sink.changed&&!sink.bytes.is_empty());assert!(error.to_string().contains("changed")||error.to_string().contains("stale"),"{error}");drop(sink);drop(restore);let mut report=Vec::new();assert!(!host.write_selected_registry_check(request(&root),options,&selectors,&mut diagnostics,&mut report).unwrap());assert!(!report.is_empty());no_products(&root);
}
